const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, LevelFormat, BorderStyle, WidthType, ShadingType,
  HeadingLevel, VerticalAlign
} = require('docx');
const fs = require('fs');

const BRAND_PINK = "D4477A";
const BRAND_LIGHT = "FDF0F5";
const BRAND_GOLD = "C9963A";
const LIGHT_GOLD = "FDF8F0";
const WHITE = "FFFFFF";
const DARK = "2D2D2D";
const MED_GRAY = "888888";

const noBorder = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const noBorders = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };

function sectionHeader(text, color = BRAND_PINK) {
  return new Paragraph({
    spacing: { before: 320, after: 80 },
    children: [
      new TextRun({
        text: text.toUpperCase(),
        bold: true,
        size: 22,
        color: color,
        font: "Arial",
      })
    ]
  });
}

function checkRow(emoji, label, note = "") {
  const checkCell = new TableCell({
    borders: noBorders,
    width: { size: 500, type: WidthType.DXA },
    margins: { top: 60, bottom: 60, left: 80, right: 40 },
    children: [new Paragraph({
      children: [new TextRun({ text: "☐", size: 22, font: "Arial", color: MED_GRAY })]
    })]
  });

  const emojiCell = new TableCell({
    borders: noBorders,
    width: { size: 420, type: WidthType.DXA },
    margins: { top: 60, bottom: 60, left: 40, right: 40 },
    children: [new Paragraph({
      children: [new TextRun({ text: emoji, size: 22, font: "Segoe UI Emoji" })]
    })]
  });

  const textChildren = [
    new TextRun({ text: label, size: 20, font: "Arial", color: DARK, bold: true })
  ];
  if (note) {
    textChildren.push(new TextRun({ text: "  —  ", size: 18, font: "Arial", color: MED_GRAY }));
    textChildren.push(new TextRun({ text: note, size: 18, font: "Arial", color: MED_GRAY, italics: true }));
  }

  const textCell = new TableCell({
    borders: noBorders,
    width: { size: 8440, type: WidthType.DXA },
    margins: { top: 60, bottom: 60, left: 80, right: 80 },
    children: [new Paragraph({ children: textChildren })]
  });

  return new TableRow({ children: [checkCell, emojiCell, textCell] });
}

function checkTable(rows) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [500, 420, 8440],
    rows: rows
  });
}

function spacer(pts = 80) {
  return new Paragraph({ spacing: { before: pts, after: 0 }, children: [] });
}

function divider(color = BRAND_PINK) {
  return new Paragraph({
    spacing: { before: 120, after: 120 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: color } },
    children: []
  });
}

const doc = new Document({
  styles: {
    default: { document: { run: { font: "Arial", size: 22, color: DARK } } }
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1080, right: 1080, bottom: 1080, left: 1080 }
      }
    },
    children: [

      // TITLE
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { before: 200, after: 60 },
        children: [
          new TextRun({ text: "🔥 YOUR CONTENT CREATOR LAUNCH CHECKLIST", bold: true, size: 34, font: "Arial", color: BRAND_PINK })
        ]
      }),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { before: 0, after: 60 },
        children: [
          new TextRun({ text: "Christian Podcast · YouTube · TikTok · Social", size: 22, font: "Arial", color: MED_GRAY, italics: true })
        ]
      }),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { before: 0, after: 240 },
        children: [
          new TextRun({ text: "No stress. Just steps. Check them off and GO.", size: 20, font: "Arial", color: BRAND_GOLD, bold: true })
        ]
      }),

      divider(BRAND_PINK),

      // PHASE 1
      sectionHeader("✦  Phase 1: Get Clear Before You Create"),
      checkTable([
        checkRow("📖", "Define your mission in one sentence", "who you serve + what you want them to feel"),
        checkRow("🎯", "Name your show / channel", "make it memorable + searchable"),
        checkRow("👤", "Get clear on your ideal listener", "who is she? where is she spiritually?"),
        checkRow("📋", "Choose your 4-5 content pillars", "rotate topics so you never run dry"),
        checkRow("🗣️", "Write your podcast description", "use for YouTube 'About' section too"),
      ]),

      spacer(200),

      // PHASE 2
      sectionHeader("✦  Phase 2: Set Up Your Tech (Simple Version)"),
      checkTable([
        checkRow("🎙️", "Create your Riverside.fm account", "riverside.fm — free plan to start"),
        checkRow("🎧", "Order a basic USB microphone", "Audio-Technica ATR2100x or similar"),
        checkRow("💡", "Find your recording spot", "good lighting + minimal echo = win"),
        checkRow("🖥️", "Test a Riverside recording", "solo recording works great to practice"),
        checkRow("📱", "Download Riverside mobile app", "for recording content on the go"),
        checkRow("🎨", "Set up Canva account", "free — for thumbnails, graphics, covers"),
        checkRow("🎵", "Choose your intro music", "royalty-free: Epidemic Sound or Pixabay"),
      ]),

      spacer(200),

      // PHASE 3
      sectionHeader("✦  Phase 3: Build Your Brand"),
      checkTable([
        checkRow("🎨", "Pick 2-3 brand colors + 1-2 fonts", "stay consistent everywhere"),
        checkRow("📸", "Take a good headshot or brand photo", "natural light, confident expression"),
        checkRow("🖼️", "Create your podcast cover art", "3000x3000px, bold, readable at small size"),
        checkRow("✍️", "Create your bio", "short version + long version"),
        checkRow("📲", "Set up your social handles", "TikTok, Instagram, YouTube — same name if possible"),
        checkRow("📧", "Start your email list", "Flodesk, Mailchimp, or ConvertKit"),
      ]),

      spacer(200),

      // PHASE 4
      sectionHeader("✦  Phase 4: Create Your First Content"),
      checkTable([
        checkRow("🎤", "Record your trailer episode", "2-3 min: who you are, what this show is about"),
        checkRow("📝", "Outline episodes 1-3", "just bullet points — not word for word"),
        checkRow("🎬", "Record episode 1 on Riverside", "done beats perfect"),
        checkRow("✂️", "Edit in Riverside", "trim the silence, cut the umms"),
        checkRow("📸", "Create your YouTube thumbnail", "bold text + your face in Canva"),
        checkRow("🎞️", "Pull one 60-sec clip for TikTok/Reels", "Riverside does this automatically"),
        checkRow("📝", "Write captions for each platform", "short + punchy for TikTok, more context for YouTube"),
      ]),

      spacer(200),

      // PHASE 5
      sectionHeader("✦  Phase 5: Launch & Show Up"),
      checkTable([
        checkRow("🚀", "Upload to your podcast host", "Buzzsprout, Spotify for Podcasters, or Anchor"),
        checkRow("📺", "Upload episode to YouTube", "add chapters, description, keywords"),
        checkRow("📱", "Post your TikTok clip", "use trending audio if it fits"),
        checkRow("📸", "Share Reel on Instagram", "add to Stories too"),
        checkRow("📣", "Announce your launch!", "tell your people — text, email, all of it"),
        checkRow("💬", "Reply to every comment in week 1", "build community from day one"),
        checkRow("📅", "Schedule your next 3 episodes", "protect your creative momentum"),
      ]),

      spacer(200),

      // WEEKLY RHYTHM
      sectionHeader("✦  Your Weekly Rhythm (Keep It Simple)", BRAND_GOLD),
      checkTable([
        checkRow("📅", "Monday — Batch record 1-2 episodes", "when energy is fresh"),
        checkRow("✂️", "Tuesday — Edit + clip in Riverside", "pull your short-form content"),
        checkRow("🖼️", "Wednesday — Create graphics in Canva", "thumbnails, quote cards"),
        checkRow("📲", "Thursday — Schedule + post everything", "use Later or Creator Studio"),
        checkRow("💬", "Friday — Engage with your community", "reply, ask questions, build relationships"),
      ]),

      divider(BRAND_GOLD),

      // RIVERSIDE CALLOUT
      new Paragraph({
        spacing: { before: 240, after: 80 },
        children: [
          new TextRun({ text: "🎙️  RIVERSIDE.FM — Your Recording Home Base", bold: true, size: 22, font: "Arial", color: BRAND_PINK })
        ]
      }),
      new Paragraph({
        spacing: { before: 0, after: 200 },
        children: [
          new TextRun({ text: "Record  →  Edit  →  Clip  →  Caption  →  Publish. All in one place. Start free at riverside.fm", size: 19, font: "Arial", color: MED_GRAY, italics: true })
        ]
      }),

      divider(BRAND_PINK),

      // MANTRA
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { before: 200, after: 80 },
        children: [
          new TextRun({
            text: "\"The lukewarm Church is waiting for someone bold enough to speak up.\"",
            bold: true, italics: true, size: 24, font: "Arial", color: BRAND_PINK
          })
        ]
      }),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { before: 0, after: 200 },
        children: [
          new TextRun({ text: "That someone is you. Now go pour some hot water. 🔥", size: 21, font: "Arial", color: BRAND_GOLD, bold: true })
        ]
      }),

    ]
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync("/mnt/user-data/outputs/Content_Creator_Checklist.docx", buffer);
  console.log("Done!");
});

