const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, LevelFormat, BorderStyle, WidthType, ShadingType,
  HeadingLevel, PageBreak
} = require('docx');
const fs = require('fs');

// Brand Colors
const PINK       = "C2185B";
const PINK_LIGHT = "FCE4EC";
const GOLD       = "B8860B";
const GOLD_LIGHT = "FFF8E1";
const PURPLE     = "6A1B9A";
const PURPLE_LIGHT = "F3E5F5";
const TEAL       = "00695C";
const TEAL_LIGHT = "E0F2F1";
const BLUE       = "1565C0";
const BLUE_LIGHT = "E3F2FD";
const ORANGE     = "E65100";
const ORANGE_LIGHT = "FFF3E0";
const DARK       = "212121";
const GRAY       = "757575";
const LIGHT_GRAY = "F5F5F5";
const WHITE      = "FFFFFF";

const noBorder = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const noBorders = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };
const softBorder = { style: BorderStyle.SINGLE, size: 1, color: "E0E0E0" };
const softBorders = { top: softBorder, bottom: softBorder, left: softBorder, right: softBorder };

function spacer(before = 120) {
  return new Paragraph({ spacing: { before, after: 0 }, children: [] });
}

function divider(color = PINK) {
  return new Paragraph({
    spacing: { before: 160, after: 160 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color, space: 1 } },
    children: []
  });
}

function pageTitle() {
  return [
    new Paragraph({
      alignment: AlignmentType.CENTER,
      spacing: { before: 160, after: 60 },
      children: [
        new TextRun({ text: "✦  AI CONTENT PROMPT BIBLE  ✦", bold: true, size: 38, font: "Arial", color: PINK })
      ]
    }),
    new Paragraph({
      alignment: AlignmentType.CENTER,
      spacing: { before: 0, after: 60 },
      children: [
        new TextRun({ text: "For the Christian Creator Who's Done Playing It Safe", italics: true, size: 24, font: "Arial", color: GRAY })
      ]
    }),
    new Paragraph({
      alignment: AlignmentType.CENTER,
      spacing: { before: 0, after: 60 },
      children: [
        new TextRun({ text: "Copy. Paste. Create. Repeat. 🔥", bold: true, size: 22, font: "Arial", color: GOLD })
      ]
    }),
    new Paragraph({
      alignment: AlignmentType.CENTER,
      spacing: { before: 0, after: 80 },
      children: [
        new TextRun({
          text: "Every prompt below is ready to copy into Claude, ChatGPT, or any AI tool. Just fill in the [brackets] with your details.",
          size: 18, font: "Arial", color: GRAY, italics: true
        })
      ]
    }),
    divider(PINK),
  ];
}

function sectionBadge(emoji, title, subtitle, bgColor, textColor = WHITE) {
  return [
    spacer(280),
    new Table({
      width: { size: 9360, type: WidthType.DXA },
      columnWidths: [9360],
      rows: [
        new TableRow({
          children: [
            new TableCell({
              borders: noBorders,
              width: { size: 9360, type: WidthType.DXA },
              shading: { fill: bgColor, type: ShadingType.CLEAR },
              margins: { top: 160, bottom: 160, left: 240, right: 240 },
              children: [
                new Paragraph({
                  children: [
                    new TextRun({ text: `${emoji}  ${title.toUpperCase()}`, bold: true, size: 28, font: "Arial", color: textColor })
                  ]
                }),
                new Paragraph({
                  spacing: { before: 40, after: 0 },
                  children: [
                    new TextRun({ text: subtitle, size: 18, font: "Arial", color: textColor, italics: true })
                  ]
                }),
              ]
            })
          ]
        })
      ]
    }),
    spacer(120),
  ];
}

function promptLabel(label, color = PINK) {
  return new Paragraph({
    spacing: { before: 200, after: 60 },
    children: [
      new TextRun({ text: `  ${label}  `, bold: true, size: 18, font: "Arial", color: WHITE,
        highlight: undefined,
      }),
    ],
    shading: { fill: color, type: ShadingType.CLEAR },
  });
}

function promptLabelPill(label, color) {
  // Use a table cell as a colored pill
  return new Table({
    width: { size: 2800, type: WidthType.DXA },
    columnWidths: [2800],
    rows: [new TableRow({
      children: [new TableCell({
        borders: noBorders,
        width: { size: 2800, type: WidthType.DXA },
        shading: { fill: color, type: ShadingType.CLEAR },
        margins: { top: 60, bottom: 60, left: 160, right: 160 },
        children: [new Paragraph({
          children: [new TextRun({ text: label, bold: true, size: 17, font: "Arial", color: WHITE })]
        })]
      })]
    })]
  });
}

function promptBox(promptText, accentColor = "F5F5F5", textColor = "333333") {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [200, 9160],
    rows: [
      new TableRow({
        children: [
          new TableCell({
            borders: noBorders,
            width: { size: 200, type: WidthType.DXA },
            shading: { fill: accentColor, type: ShadingType.CLEAR },
            margins: { top: 120, bottom: 120, left: 0, right: 0 },
            children: [new Paragraph({ children: [] })]
          }),
          new TableCell({
            borders: { ...noBorders, left: { style: BorderStyle.NONE, size: 0, color: WHITE } },
            width: { size: 9160, type: WidthType.DXA },
            shading: { fill: LIGHT_GRAY, type: ShadingType.CLEAR },
