                children: [
                  new TextRun({ text: promptText, size: 19, font: "Courier New", color: DARK })
                ]
              })
            ]
          })
        ]
      })
    ]
  });
}

function promptBlock(labelText, labelColor, promptText, tipText = null) {
  const items = [
    spacer(160),
    promptLabelPill(labelText, labelColor),
    spacer(60),
    promptBox(promptText, labelColor),
  ];
  if (tipText) {
    items.push(spacer(60));
    items.push(new Paragraph({
      spacing: { before: 0, after: 0 },
      children: [
        new TextRun({ text: "💡 Tip: ", bold: true, size: 17, font: "Arial", color: labelColor }),
        new TextRun({ text: tipText, size: 17, font: "Arial", color: GRAY, italics: true })
      ]
    }));
  }
  return items;
}

function howToUseBox() {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [new TableRow({
      children: [new TableCell({
